static z_t1533_t z_os_env(z_t81_t key) {
    z_t1533_t out = {0};
    char* key_cstr = z_sv_to_cstr(key);
    const char* v = getenv(key_cstr);
    free(key_cstr);
    if (v == NULL) {
        out.tag = Z_T1533_TAG_0;
        return out;
    }
    z_t61_t* boxed = (z_t61_t*)z_xmalloc(sizeof(z_t61_t));
    *boxed = z_t61_new(v);
    out.tag = Z_T1533_TAG_1;
    out.data = boxed;
    return out;
}


